function processarUsuarios(users: any[]) {
  let resultado: any[] = [];

  for (let i = 0; i < users.length; i++) {
    if (users[i].ativo === true) {
      let nome = users[i].nome;
      let email = users[i].email;

      if (nome !== undefined && nome !== null && nome !== "") {
        if (email !== undefined && email !== null && email !== "") {
          resultado.push({
            nome: nome,
            email: email,
            status: "ativo"
          });
        }
      }
    }
  }

  return resultado;
}

